  ('NZ', 'New Zealand', 'Small classes and development-focused government scholarships.', 5),
  ('IE', 'Ireland', 'An English-speaking EU hub with a growing research sector.', 6),
  ('DE', 'Germany', 'Low or no tuition at public universities, plus DAAD funding.', 7),
  ('NL', 'Netherlands', 'Many English-taught programmes at research-led universities.', 8),
  ('CH', 'Switzerland', 'Government excellence awards for doctoral research.', 9),
  ('SE', 'Sweden', 'Funding for future leaders, with a strong sustainability focus.', 10),
  ('JP', 'Japan', 'MEXT funding includes research-student periods before degrees.', 11),
