insert into public.scholarships (id, name, funder, funder_type, award_type, destination_code, university_id, levels, disciplines_all, disciplines, discipline_label, opens, closes, deadline_note, awards, summary, official_url, last_verified, verification_status, human_check_note, eligibility, documents, timeline, where_usable) values
  ('chevening', 'Chevening Scholarships', 'UK Government (FCDO)', 'Government', 'Scholarship', 'GB', null, '{M}'::public.level_code[], true, '{}'::text[], null, '2026-08-04', '2026-10-06', 'Closed 6 Oct 2026, 11:00 UTC. The 2028/29 round is expected to open in August 2027.', 'Not published per country', 'One-year master''s at a UK university for future leaders.', 'https://www.chevening.org/scholarships/', '2026-10-22', 'checked', null, array['I am a Sri Lankan citizen and will return to Sri Lanka for at least two years after the award', 'I hold an undergraduate degree equivalent to a UK 2:2 (Second Class Lower) or above', 'I have at least 2,800 hours of work experience gained after my undergraduate degree', 'I have applied to three different eligible UK master''s courses', 'I can meet the English-language requirement by the published date']::text[], array['Degree transcripts', 'Two references', 'Four essays (leadership, networking, why the UK, career plan)', 'Passport or national ID', 'English language certificate']::text[], '[{"label":"Applications open","when":"4 Aug 2026, 11:00 UTC"},{"label":"Applications close","when":"6 Oct 2026, 11:00 UTC"},{"label":"Eligibility checks and reading committees","when":"Oct 2026 – Jan 2027"},{"label":"Interview (if shortlisted)","when":"Feb – Apr 2027"},{"label":"Results","when":"Mid-June 2027"},{"label":"Deadline to hold an unconditional university offer","when":"8 Jul 2027"},{"label":"Study starts in the UK","when":"Sep – Oct 2027"}]'::jsonb, 'Most UK universities, for an eligible one-year taught master''s. Examples from the ranked list:'),
  ('commonwealth', 'Commonwealth Master''s and PhD Scholarships', 'Commonwealth Scholarship Commission', 'Government', 'Scholarship', 'GB', null, '{M,P}'::public.level_code[], false, array['Social Sciences', 'Life Sciences', 'Engineering & Technology', 'Clinical & Health']::text[], 'Development-focused subjects', '2026-09-08', '2026-10-20', 'CSC deadline 20 Oct 2026, 16:00 BST. You apply through a national nominating agency, which may close earlier.', null, null, 'https://cscuk.fcdo.gov.uk/scholarships/', '2026-10-22', 'checked', null, null, null, null, null),
  ('gates', 'Gates Cambridge Scholarship', 'University of Cambridge', 'University', 'Scholarship', 'GB', 'university-of-cambridge', '{M,R,P}'::public.level_code[], true, '{}'::text[], null, '2026-09-11', '2026-12-08', 'International round closes 8 Dec 2026 or 6 Jan 2027, depending on your course. Check the Cambridge course directory.', 'About 80 a year (about 55 in the international round)', null, 'https://www.gatescambridge.org/', '2026-10-22', 'checked', null, null, null, null, null),
  ('clarendon', 'Clarendon Fund', 'University of Oxford', 'University', 'Scholarship', 'GB', 'university-of-oxford', '{M,P}'::public.level_code[], true, '{}'::text[], null, '2026-09-01', '2027-01-26', 'No separate application. Apply for your Oxford course by its December 2026 or January 2027 deadline (12 noon UK time) to be considered automatically.', '200+ new awards a year', null, 'https://www.ox.ac.uk/clarendon', '2026-10-26', 'checked', null, null, null, null, null),
  ('fulbright', 'Fulbright Foreign Student Program', 'US Department of State', 'Government', 'Scholarship', 'US', null, '{M,P}'::public.level_code[], true, '{}'::text[], null, '2027-02-01', '2027-05-31', 'Expected dates. The US–Sri Lanka Fulbright Commission deadline is 31 May each year; interviews in July–August. Needs a 4-year degree and 1 year of work experience.', null, null, 'https://fulbrightsrilanka.org/award/masters-scholarship/', '2026-10-26', 'expected_or_to_confirm', null, null, null, null, null),
  ('usneed', 'Need-based aid for international undergraduates', 'MIT, Harvard, Princeton, Yale and others', 'University', 'Scholarship', 'US', null, '{B}'::public.level_code[], true, '{}'::text[], null, '2026-08-01', '2027-01-01', 'Varies by university. Most regular-decision deadlines fall around 1–5 Jan 2027, with the CSS Profile and financial documents due near the same date. Check each university''s financial aid page.', null, null, 'https://educationusa.state.gov/', '2026-10-26', 'expected_or_to_confirm', 'Deadline varies by university; confirm per institution.', null, null, null, null),
  ('ausawards', 'Australia Awards Scholarships', 'Australian Government (DFAT)', 'Government', 'Scholarship', 'AU', null, '{M}'::public.level_code[], true, '{}'::text[], null, '2027-02-01', '2027-04-30', 'Expected dates. The Sri Lanka office says applications reopen in early 2027; last cycle ran 1 Feb – 30 Apr.', null, null, 'https://australiaawardssrilanka.org/', '2026-10-22', 'expected_or_to_confirm', null, null, null, null, null),
  ('rtp', 'Research Training Program scholarships', 'Australian Government via universities', 'Government', 'Scholarship', 'AU', null, '{R,P}'::public.level_code[], true, '{}'::text[], null, '2026-07-01', '2026-10-31', 'Varies by university. Each Australian university runs its own RTP rounds, often closing around 31 Oct for the next year. Check your target university''s graduate research page.', null, null, 'https://www.education.gov.au/research-block-grants/research-training-program', '2026-10-26', 'expected_or_to_confirm', 'Deadline varies by university; confirm per institution.', null, null, null, null),
  ('mgrs', 'Melbourne Graduate Research Scholarship', 'University of Melbourne', 'University', 'Scholarship', 'AU', 'university-of-melbourne', '{R,P}'::public.level_code[], true, '{}'::text[], null, '2026-08-01', '2026-10-31', 'No separate application. Apply for your research degree by 31 Oct 2026 (Semester 1) or 31 Mar 2027 (Semester 2).', 'About 600 a year', null, 'https://scholarships.unimelb.edu.au/awards/graduate-research-scholarships', '2026-10-26', 'checked', null, null, null, null, null),
  ('miu', 'Melbourne International Undergraduate Scholarship', 'University of Melbourne', 'University', 'Scholarship', 'AU', 'university-of-melbourne', '{B}'::public.level_code[], true, '{}'::text[], null, '2026-08-01', '2026-11-30', 'No separate application. Apply for your bachelor''s by 30 Nov 2026 for Semester 1, 2027. For citizens of listed lower-income countries; confirm Sri Lanka is on the list.', '225 from 2027', null, 'https://scholarships.unimelb.edu.au/', '2026-10-26', 'checked', 'Confirm the eligible country list.', null, null, null, null),
  ('pearson', 'Lester B. Pearson International Scholarship', 'University of Toronto', 'University', 'Scholarship', 'CA', 'university-of-toronto', '{B}'::public.level_code[], true, '{}'::text[], null, '2026-07-06', '2026-11-06', 'Your school must nominate you by 9 Oct 2026 and you apply to U of T by 16 Oct. Pearson form and documents due 6 Nov 2026.', 'About 37 a year', null, 'https://future.utoronto.ca/pearson/', '2026-10-26', 'checked', null, null, null, null, null),
  ('manaaki', 'Manaaki New Zealand Scholarships', 'New Zealand Government', 'Government', 'Scholarship', 'NZ', null, '{M,P}'::public.level_code[], true, '{}'::text[], null, '2027-03-01', '2027-04-10', 'To confirm: the eligible country list changed recently. Check Sri Lanka is listed before applying. Expected window 1 Mar – 10 Apr 2027.', null, null, 'https://www.nzscholarships.govt.nz/', '2026-10-26', 'expected_or_to_confirm', 'Sri Lanka may no longer be on the eligible country list.', null, null, null, null),
  ('ireland', 'Government of Ireland International Education Scholarships', 'Higher Education Authority', 'Government', 'Scholarship', 'IE', null, '{M,P}'::public.level_code[], true, '{}'::text[], null, '2027-01-29', '2027-03-12', 'Expected dates, based on the 2026 call (29 Jan – 12 Mar, 5 pm Irish time). You need an offer from an Irish university before you apply.', 'About 60 a year', null, 'https://hea.ie/', '2026-10-26', 'expected_or_to_confirm', null, null, null, null, null),
  ('daad', 'DAAD Scholarships', 'German Academic Exchange Service', 'Government', 'Scholarship', 'DE', null, '{M,P}'::public.level_code[], true, '{}'::text[], null, '2026-06-15', '2026-10-15', 'Each EPOS course sets its own deadline; most for October 2027 entry fell between August and October 2026. Needs 2 years of work experience.', null, 'Development-related postgraduate courses in Germany.', 'https://www.daad.de/epos', '2026-10-26', 'checked', null, null, null, null, null),
  ('holland', 'NL Scholarship (formerly Holland Scholarship)', 'Dutch Government and universities', 'Government', 'Scholarship', 'NL', null, '{B,M}'::public.level_code[], true, '{}'::text[], null, '2026-11-01', '2027-02-01', 'No national deadline: each university sets its own, often 1 Feb 2027 and some as late as 1 May.', null, null, 'https://www.studyinnl.org/', '2026-10-26', 'checked', null, null, null, null, null),
  ('swiss', 'Swiss Government Excellence Scholarships', 'Swiss Confederation (FCS)', 'Government', 'Scholarship', 'CH', null, '{P}'::public.level_code[], true, '{}'::text[], null, '2026-08-20', '2026-11-30', 'Deadline is set per country — confirm Sri Lanka''s date on the SERI list. A Swiss professor must agree to supervise you before you apply.', null, null, 'https://www.sbfi.admin.ch/scholarships_eng', '2026-10-26', 'checked', 'The deadline is country-specific; confirm the Sri Lanka date.', null, null, null, null),
  ('si', 'Swedish Institute Scholarships for Global Professionals', 'Swedish Institute', 'Government', 'Scholarship', 'SE', null, '{M}'::public.level_code[], true, '{}'::text[], null, '2027-02-08', '2027-02-24', 'First apply to an eligible master''s through University Admissions by 15 Jan 2027. SI portal open 8–24 Feb 2027, closing 14:59 CET. Results 22 Apr 2027.', null, null, 'https://si.se/en/apply/scholarships/swedish-institute-scholarships-for-global-professionals/', '2026-10-26', 'checked', null, null, null, null, null),
  ('mext', 'MEXT (Japanese Government) Scholarship', 'Japanese Government', 'Government', 'Scholarship', 'JP', null, '{B,M,R,P}'::public.level_code[], true, '{}'::text[], null, '2027-04-20', '2027-05-18', 'Expected dates. Sri Lankans apply online through the Ministry of Higher Education portal; the 2027 round closed 18 May 2026.', null, null, 'https://foreignscholarships.mohe.gov.lk/', '2026-10-26', 'expected_or_to_confirm', null, null, null, null, null),
