  ('csc', 'Chinese Government Scholarship', 'China Scholarship Council', 'Government', 'Scholarship', 'CN', null, '{B,M,P}'::public.level_code[], true, '{}'::text[], null, '2026-11-15', '2027-03-31', 'Expected dates. Sri Lankan undergraduates apply through the Ministry of Higher Education portal (last round closed 6 Dec 2025). For master''s and PhD, apply through the embassy or a university, roughly Jan – Apr 2027, at campuschina.org. You need a pre-admission letter.', null, null, 'https://www.campuschina.org/', '2026-10-26', 'expected_or_to_confirm', null, null, null, null, null),
  ('schwarzman', 'Schwarzman Scholars', 'Schwarzman Scholars (at Tsinghua)', 'Foundation', 'Scholarship', 'CN', null, '{M}'::public.level_code[], true, '{}'::text[], null, '2027-04-08', '2027-09-09', 'Expected window for the Class of 2028–29 (last cycle 8 Apr – 9 Sep, 3 pm EDT). You must be 18–28 on 1 Aug 2028.', null, null, 'https://www.schwarzmanscholars.org/admissions/', '2026-10-26', 'expected_or_to_confirm', null, null, null, null, null),
