  ('erasmus', 'Erasmus Mundus Joint Master''s', 'European Union', 'Multi-country programme', 'Scholarship', 'EU', null, '{M}'::public.level_code[], true, '{}'::text[], null, '2026-10-01', '2027-01-15', 'Each programme sets its own deadline, usually between October and January. Scholarship deadlines can be earlier than admission deadlines.', null, 'Study one master''s across two or more European countries.', 'https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en', '2026-10-22', 'checked', null, null, null, null, null),
  ('msca', 'Marie Skłodowska-Curie Doctoral Networks', 'European Union', 'Multi-country programme', 'Research grant', 'EU', null, '{P}'::public.level_code[], true, '{}'::text[], null, '2027-05-01', '2028-06-30', 'You don''t apply to the EU call: its 24 Nov 2026 deadline is for university consortia. Funded networks advertise salaried PhD vacancies on EURAXESS from mid-2027, each with its own deadline. Any nationality; no PhD at recruitment.', null, null, 'https://euraxess.ec.europa.eu/jobs/search', '2026-10-26', 'checked', null, null, null, null, null)
