-- Generated by scripts/generate-seed.ts from design/data/*.json. Do not edit by hand.
-- Ranks: THE World University Rankings 2027 as recorded in the brief (design/data/universities.json).
-- Seeding never overwrites a rank already edited in the admin (on conflict do nothing).
begin;

on conflict (code) do update set name = excluded.name, why = excluded.why, sort_order = excluded.sort_order;

on conflict (slug) do update set name = excluded.name, includes = excluded.includes, sort_order = excluded.sort_order;

on conflict (id) do update set name = excluded.name, city = excluded.city, country_code = excluded.country_code, levels = excluded.levels;

on conflict (university_id, year) do nothing;

on conflict (id) do update set name = excluded.name, funder = excluded.funder, funder_type = excluded.funder_type, award_type = excluded.award_type, destination_code = excluded.destination_code, university_id = excluded.university_id, levels = excluded.levels, disciplines_all = excluded.disciplines_all, disciplines = excluded.disciplines, discipline_label = excluded.discipline_label, opens = excluded.opens, closes = excluded.closes, deadline_note = excluded.deadline_note, awards = excluded.awards, summary = excluded.summary, official_url = excluded.official_url, last_verified = excluded.last_verified, verification_status = excluded.verification_status, human_check_note = excluded.human_check_note, eligibility = excluded.eligibility, documents = excluded.documents, timeline = excluded.timeline, where_usable = excluded.where_usable;

on conflict do nothing;

select v.id, v.verified::timestamptz, v.status::public.verification_status, 'Imported from the design handoff'
from (values
  ('chevening', '2026-10-22', 'checked'),
  ('commonwealth', '2026-10-22', 'checked'),
  ('gates', '2026-10-22', 'checked'),
  ('clarendon', '2026-10-26', 'checked'),
  ('fulbright', '2026-10-26', 'expected_or_to_confirm'),
  ('usneed', '2026-10-26', 'expected_or_to_confirm'),
  ('ausawards', '2026-10-22', 'expected_or_to_confirm'),
  ('rtp', '2026-10-26', 'expected_or_to_confirm'),
  ('mgrs', '2026-10-26', 'checked'),
  ('miu', '2026-10-26', 'checked'),
  ('pearson', '2026-10-26', 'checked'),
  ('manaaki', '2026-10-26', 'expected_or_to_confirm'),
  ('ireland', '2026-10-26', 'expected_or_to_confirm'),
  ('daad', '2026-10-26', 'checked'),
  ('holland', '2026-10-26', 'checked'),
  ('swiss', '2026-10-26', 'checked'),
  ('si', '2026-10-26', 'checked'),
  ('mext', '2026-10-26', 'expected_or_to_confirm'),
  ('gks', '2026-10-26', 'expected_or_to_confirm'),
  ('csc', '2026-10-26', 'expected_or_to_confirm'),
  ('schwarzman', '2026-10-26', 'expected_or_to_confirm'),
  ('singa', '2026-10-26', 'expected_or_to_confirm'),
  ('hkpfs', '2026-10-26', 'checked'),
  ('hungaricum', '2026-10-22', 'expected_or_to_confirm'),
  ('erasmus', '2026-10-22', 'checked'),
  ('msca', '2026-10-26', 'checked')
) as v (id, verified, status)
where not exists (select 1 from public.verification_log l where l.scholarship_id = v.id);

commit;
